#!/usr/bin/env node
/**
 * Installs the Readstein icon set into the generated Android project.
 *
 * The launcher icon lives in src-tauri/gen/, which is gitignored and regenerated by
 * `tauri android init`. Without this step the Android build keeps whatever the template
 * shipped -- which is how the phone ended up showing the upstream Readest mark while the
 * desktop showed Readstein.
 *
 * The adaptive-icon XML is written here rather than copied from the icon generator's
 * output: that template references @mipmap/ic_launcher_background, but this project keeps
 * its background as a colour (@color/ic_launcher_background) and has no mipmap by that
 * name, so a straight copy fails the resource link with
 * "resource mipmap/ic_launcher_background not found". Every reference is asserted below
 * so that mismatch cannot reach a build again.
 *
 * Run after `tauri android init` and before building. Safe to run repeatedly.
 */
import { writeFileSync, existsSync, mkdirSync, copyFileSync, readdirSync } from 'node:fs';
import { join, relative } from 'node:path';

const appDir = process.argv[2] ?? '.';
const iconsRoot = join(appDir, 'src-tauri/icons/android');
const resDir = join(appDir, 'src-tauri/gen/android/app/src/main/res');

if (!existsSync(iconsRoot)) {
  console.error(`No Android icon source at ${iconsRoot}. Run \`pnpm exec tauri icon <master.png>\` first.`);
  process.exit(1);
}
if (!existsSync(resDir)) {
  console.error(`No generated Android project at ${resDir}. Run \`tauri android init\` first.`);
  process.exit(1);
}

let copied = 0;
for (const entry of readdirSync(iconsRoot, { withFileTypes: true })) {
  if (!entry.isDirectory() || !entry.name.startsWith('mipmap-')) continue;
  const dest = join(resDir, entry.name);
  mkdirSync(dest, { recursive: true });
  for (const file of readdirSync(join(iconsRoot, entry.name))) {
    if (file.endsWith('.xml')) continue; // the adaptive definition is written below
    copyFileSync(join(iconsRoot, entry.name, file), join(dest, file));
    copied += 1;
  }
}

const manifestDir = join(resDir, 'mipmap-anydpi-v26');
mkdirSync(manifestDir, { recursive: true });
const adaptive = [
  '<adaptive-icon xmlns:android="http://schemas.android.com/apk/res/android">',
  '    <background android:drawable="@color/ic_launcher_background"/>',
  '    <foreground android:drawable="@mipmap/ic_launcher_foreground"/>',
  '    <monochrome android:drawable="@mipmap/ic_launcher_monochrome"/>',
  '</adaptive-icon>',
  '',
].join('\n');
writeFileSync(join(manifestDir, 'ic_launcher.xml'), adaptive);

// every reference above must resolve to something real, or the resource link fails
const missing = [];
const anyDpi = readdirSync(join(resDir, 'mipmap-xxxhdpi'));
for (const [label, ok] of [
  ['color/ic_launcher_background', existsSync(join(resDir, 'values/ic_launcher_background.xml'))],
  ['mipmap/ic_launcher_foreground', anyDpi.includes('ic_launcher_foreground.png')],
  ['mipmap/ic_launcher_monochrome', anyDpi.includes('ic_launcher_monochrome.png')],
]) {
  if (!ok) missing.push(label);
}
if (missing.length) {
  console.error(`Adaptive icon references missing resources: ${missing.join(', ')}`);
  process.exit(1);
}

console.log(`installed ${copied} icon files and wrote ${relative(appDir, join(manifestDir, 'ic_launcher.xml'))}`);
